/**
 * @file catalog.cpp
 * @brief Keep built-in tool names and schemas deterministic across model requests and editors.
 */
#include "tools/catalog.hpp"

#include "common/json.hpp"

namespace tools {
    /**
     * @brief Return deterministic built-in names, descriptions, schemas, and group restrictions.
     * @return Complete tool catalog.
     */
    auto builtin_catalog() -> Json::Value {
        static auto const catalog{ common::parse_json(R"catalog([{"name":"reply","description":"Send a final text reply and finish this turn.","parameters":{"type":"object","properties":{"content":{"type":"string","maxLength":8192}},"required":["content"],"additionalProperties":false},"group_only":false},{"name":"no_reply","description":"Finish this turn without sending a reply.","parameters":{"type":"object","properties":{},"required":[],"additionalProperties":false},"group_only":false},{"name":"reply_with_quote","description":"Send a final reply quoting a message ID from this conversation.","parameters":{"type":"object","properties":{"content":{"type":"string","maxLength":8192},"message_id":{"type":"string","maxLength":8192}},"required":["content","message_id"],"additionalProperties":false},"group_only":false},{"name":"reply_and_continue","description":"Send text to the current conversation and continue working.","parameters":{"type":"object","properties":{"content":{"type":"string","maxLength":8192}},"required":["content"],"additionalProperties":false},"group_only":false},{"name":"deep_think","description":"Ask the configured thinking model one self-contained question.","parameters":{"type":"object","properties":{"question":{"type":"string","maxLength":8192}},"required":["question"],"additionalProperties":false},"group_only":false},{"name":"ask_images","description":"Ask the vision model about HTTP image URLs supplied in this conversation.","parameters":{"type":"object","properties":{"question":{"type":"string","maxLength":8192},"images":{"type":"array","items":{"type":"string","maxLength":2048},"maxItems":32}},"required":["question","images"],"additionalProperties":false},"group_only":false},{"name":"recall_memory","description":"Recall relevant long-term memories from this conversation.","parameters":{"type":"object","properties":{"query":{"type":"string","maxLength":8192}},"required":["query"],"additionalProperties":false},"group_only":false},{"name":"save_memory","description":"Save an explicitly stated durable fact for this conversation.","parameters":{"type":"object","properties":{"content":{"type":"string","maxLength":8192}},"required":["content"],"additionalProperties":false},"group_only":false},{"name":"delete_memory","description":"Delete one memory from this conversation using its ID and revision.","parameters":{"type":"object","properties":{"id":{"type":"string","maxLength":8192},"revision":{"type":"string","maxLength":8192}},"required":["id","revision"],"additionalProperties":false},"group_only":false},{"name":"list_scheduled_tasks","description":"List pending reminders in the current conversation.","parameters":{"type":"object","properties":{},"required":[],"additionalProperties":false},"group_only":false},{"name":"create_scheduled_task","description":"Create a reminder in this conversation. due_at is future UTC Unix seconds; daily repeats every 24 hours.","parameters":{"type":"object","properties":{"due_at":{"type":"integer"},"content":{"type":"string","maxLength":8192},"daily":{"type":"boolean"}},"required":["due_at","content"],"additionalProperties":false},"group_only":false},{"name":"cancel_scheduled_task","description":"Cancel one pending reminder belonging to this conversation.","parameters":{"type":"object","properties":{"id":{"type":"string","maxLength":8192}},"required":["id"],"additionalProperties":false},"group_only":false},{"name":"send_face","description":"Send one QQ face to the current conversation.","parameters":{"type":"object","properties":{"id":{"type":"integer"}},"required":["id"],"additionalProperties":false},"group_only":false},{"name":"send_image","description":"Send an HTTP(S) image URL to the current conversation.","parameters":{"type":"object","properties":{"url":{"type":"string","maxLength":8192}},"required":["url"],"additionalProperties":false},"group_only":false},{"name":"generate_image","description":"Generate an image using the image role; optionally edit the saved character reference.","parameters":{"type":"object","properties":{"prompt":{"type":"string","maxLength":8192},"use_self_reference":{"type":"boolean"}},"required":["prompt"],"additionalProperties":false},"group_only":false},{"name":"list_stickers","description":"List NapCat favourite resource IDs, descriptions, and image URLs.","parameters":{"type":"object","properties":{},"required":[],"additionalProperties":false},"group_only":false},{"name":"send_sticker","description":"Send a favourite sticker selected by its resource ID.","parameters":{"type":"object","properties":{"res_id":{"type":"string","maxLength":8192}},"required":["res_id"],"additionalProperties":false},"group_only":false},{"name":"rename_sticker","description":"Set the description of a favourite sticker by resource ID.","parameters":{"type":"object","properties":{"res_id":{"type":"string","maxLength":8192},"description":{"type":"string","maxLength":8192}},"required":["res_id","description"],"additionalProperties":false},"group_only":false},{"name":"delete_sticker","description":"Delete a favourite sticker by resource ID.","parameters":{"type":"object","properties":{"res_id":{"type":"string","maxLength":8192}},"required":["res_id"],"additionalProperties":false},"group_only":false},{"name":"at_user","description":"Send a QQ mention to the current group.","parameters":{"type":"object","properties":{"qq":{"type":"string","maxLength":8192}},"required":["qq"],"additionalProperties":false},"group_only":true},{"name":"ban_user","description":"Mute or unmute a member of the current group. duration is 0..2592000 seconds; 0 unmutes.","parameters":{"type":"object","properties":{"qq":{"type":"string","maxLength":8192},"duration":{"type":"integer"}},"required":["qq","duration"],"additionalProperties":false},"group_only":true},{"name":"mcp_list_tools","description":"Discover tool names and descriptions from a configured MCP service; cursor is a page offset.","parameters":{"type":"object","properties":{"server":{"type":"string","maxLength":8192},"query":{"type":"string","maxLength":8192},"cursor":{"type":"integer"}},"required":["server"],"additionalProperties":false},"group_only":false},{"name":"mcp_enable_tools","description":"Enable selected MCP tools for subsequent requests in this turn.","parameters":{"type":"object","properties":{"server":{"type":"string","maxLength":8192},"names":{"type":"array","items":{"type":"string","maxLength":2048},"maxItems":32}},"required":["server","names"],"additionalProperties":false},"group_only":false}])catalog") };
        return catalog;
    }

    /**
     * @brief Test whether a name belongs to the built-in catalog.
     * @param name Candidate tool name.
     * @return Whether custom tools must avoid the name.
     */
    auto is_builtin(std::string const& name) -> bool {
        for (auto const& tool : builtin_catalog()) {
            if (tool["name"].asString() == name) {
                return true;
            }
        }
        return false;
    }
} // namespace tools
